files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e2430;
  --bg-accent: #2a3242;
  --card: #f4f1ea;
  --ink: #23272f;
  --muted: #5c6470;
  --accent: #c8622f;
  --accent-dark: #a34d22;
  --available: #2f7d5c;
  --checked: #9a3b3b;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
  background: radial-gradient(circle at 20% 10%, var(--bg-accent), var(--bg) 70%);
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 28px 24px 24px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

.header h1 {
  margin: 0 0 6px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 1rem;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  margin-bottom: 18px;
  background: #e6e1d6;
  border-radius: var(--radius);
}

.filter-toggle {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  font-weight: 600;
  padding: 4px 2px;
  border-radius: 6px;
}

.filter-toggle input {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.filter-toggle:focus-within {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.count {
  margin: 0;
  font-weight: 600;
  color: var(--accent-dark);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid #d8d2c4;
  border-radius: var(--radius);
  background: #fffdf8;
}

.book-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.book-title {
  font-weight: 600;
  font-size: 1rem;
  overflow-wrap: anywhere;
}

.status {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.status.available { color: var(--available); }
.status.checked { color: var(--checked); }

button {
  font: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 10px 16px;
  border: none;
  border-radius: 8px;
  color: #fff;
  background: var(--accent);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease;
  flex-shrink: 0;
}

button:hover { background: var(--accent-dark); }

button:focus-visible {
  outline: 3px solid var(--accent-dark);
  outline-offset: 2px;
}

button:active { transform: translateY(1px); }

button.return { background: var(--available); }
button.return:hover { background: #256349; }
button.return:focus-visible { outline-color: #256349; }

.empty {
  margin: 18px 0 0;
  text-align: center;
  color: var(--muted);
  font-style: italic;
}

@media (max-width: 420px) {
  .card { padding: 22px 16px; }
  .book { flex-direction: column; align-items: stretch; }
  button { width: 100%; }
}

"use strict";

const BOOKS = [
  { id: 1, title: "The Pixel Forest", checkedOut: false },
  { id: 2, title: "Signals & Systems", checkedOut: true },
  { id: 3, title: "A Short History of CSS", checkedOut: false },
  { id: 4, title: "The Midnight Compiler", checkedOut: false },
  { id: 5, title: "Rendering Realms", checkedOut: true },
  { id: 6, title: "Notes on Nothing", checkedOut: false }
];

const listEl = document.getElementById("book-list");
const filterEl = document.getElementById("available-filter");
const countEl = document.getElementById("checked-count");
const emptyEl = document.getElementById("empty-message");

function checkedOutCount() {
  return BOOKS.filter((b) => b.checkedOut).length;
}

function render() {
  const availableOnly = filterEl.checked;
  const visible = BOOKS.filter((b) => !availableOnly || !b.checkedOut);

  listEl.innerHTML = "";

  visible.forEach((book) => {
    const li = document.createElement("li");
    li.className = "book";

    const info = document.createElement("div");
    info.className = "book-info";

    const title = document.createElement("span");
    title.className = "book-title";
    title.textContent = book.title;

    const status = document.createElement("span");
    status.className = "status " + (book.checkedOut ? "checked" : "available");
    status.textContent = book.checkedOut ? "Checked out" : "Available";

    info.appendChild(title);
    info.appendChild(status);

    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = book.checkedOut ? "Return" : "Check out";
    if (book.checkedOut) btn.classList.add("return");
    btn.setAttribute(
      "aria-label",
      (book.checkedOut ? "Return " : "Check out ") + book.title
    );
    btn.addEventListener("click", () => {
      book.checkedOut = !book.checkedOut;
      render();
    });

    li.appendChild(info);
    li.appendChild(btn);
    listEl.appendChild(li);
  });

  emptyEl.hidden = visible.length !== 0;
  countEl.textContent = "Checked out: " + checkedOutCount();
}

filterEl.addEventListener("change", render);

render();
